// ============================================================================
// cnn_top_tb.sv — Testbench for MNIST CNN accelerator
//
// Verification strategy:
//   1. export_hex.py generates quantized weights (.hex), test images, and
//      golden expected predictions (from Python quantized forward pass)
//   2. This TB loads those hex files, drives the DUT image-by-image,
//      and compares pred_class against the golden expected class.
//   3. Reports per-image PASS/FAIL and overall accuracy.
//
// Files required in simulation working directory (generated by export_hex.py):
//   conv1_weights.hex, conv1_bias.hex, conv2_weights.hex, conv2_bias.hex
//   fc1_weights.hex, fc1_bias.hex, fc2_weights.hex, fc2_bias.hex
//   test_images.hex, test_expected.hex
//   requant_params.svh, num_test.svh
// ============================================================================

`timescale 1ns / 1ps

module cnn_top_tb;

  import cnn_pkg::*;

  // ─── Generated includes ───
  `include "requant_params.svh"   // CONV1_RQ_MULT, CONV1_RQ_SHIFT, etc.
  `include "num_test.svh"         // NUM_TEST_IMAGES

  // ─── Clock and reset ───
  localparam CLK_PERIOD = 10;  // 100 MHz
  logic clk = 0;
  always #(CLK_PERIOD/2) clk = ~clk;

  logic rst_n;

  // ─── DUT signals ───
  logic        img_wr_en;
  logic [9:0]  img_wr_addr;
  logic signed [7:0] img_wr_data;

  logic        start;
  logic        done;
  logic [3:0]  pred_class;
  logic        busy;

  // ─── DUT instantiation ───
  cnn_top u_dut (
    .clk           (clk),
    .rst_n         (rst_n),
    .img_wr_en     (img_wr_en),
    .img_wr_addr   (img_wr_addr),
    .img_wr_data   (img_wr_data),
    .start         (start),
    .done          (done),
    .pred_class    (pred_class),
    .busy          (busy),
    .conv1_rq_mult (CONV1_RQ_MULT),
    .conv1_rq_shift(CONV1_RQ_SHIFT),
    .conv2_rq_mult (CONV2_RQ_MULT),
    .conv2_rq_shift(CONV2_RQ_SHIFT),
    .fc1_rq_mult   (FC1_RQ_MULT),
    .fc1_rq_shift  (FC1_RQ_SHIFT)
  );

  // ─── Test data memory ───
  // test_images.hex: NUM_TEST_IMAGES * 784 entries (int8)
  // test_expected.hex: NUM_TEST_IMAGES entries (class 0–9)
  localparam int PIXELS_PER_IMAGE = IMG_SIZE;  // 784

  logic signed [7:0] test_images  [0:NUM_TEST_IMAGES * PIXELS_PER_IMAGE - 1];
  logic        [7:0] test_expected[0:NUM_TEST_IMAGES - 1];

  initial begin
    $readmemh("test_images.hex",   test_images);
    $readmemh("test_expected.hex", test_expected);
  end

  // ─── Timeout parameters ───
  // Worst case: ~78K cycles per image (from mapping.md) + margin
  localparam int TIMEOUT_CYCLES = 200_000;

  // ─── Test procedure ───
  int pass_count;
  int fail_count;
  int img_idx;
  int pixel_offset;
  int timeout_cnt;

  initial begin
    // Initialize signals
    rst_n       = 1'b0;
    img_wr_en   = 1'b0;
    img_wr_addr = '0;
    img_wr_data = '0;
    start       = 1'b0;
    pass_count  = 0;
    fail_count  = 0;

    // Reset
    repeat (5) @(posedge clk);
    rst_n = 1'b1;
    repeat (2) @(posedge clk);

    $display("============================================================");
    $display("  CNN Top Testbench — %0d test images", NUM_TEST_IMAGES);
    $display("============================================================");

    // ── Loop over test images ──
    for (img_idx = 0; img_idx < NUM_TEST_IMAGES; img_idx++) begin
      pixel_offset = img_idx * PIXELS_PER_IMAGE;

      // Load image into input BRAM (784 pixels)
      for (int p = 0; p < PIXELS_PER_IMAGE; p++) begin
        @(posedge clk);
        img_wr_en   <= 1'b1;
        img_wr_addr <= p[9:0];
        img_wr_data <= test_images[pixel_offset + p];
      end
      @(posedge clk);
      img_wr_en <= 1'b0;

      // Wait one cycle to ensure last write completes
      @(posedge clk);

      // Pulse start
      @(posedge clk);
      start <= 1'b1;
      @(posedge clk);
      start <= 1'b0;

      // Wait for done with timeout
      timeout_cnt = 0;
      while (!done && timeout_cnt < TIMEOUT_CYCLES) begin
        @(posedge clk);
        timeout_cnt++;
      end

      if (timeout_cnt >= TIMEOUT_CYCLES) begin
        $display("  Image %3d: TIMEOUT after %0d cycles (state=%0d)",
                 img_idx, TIMEOUT_CYCLES, u_dut.top_state);
        fail_count++;
      end else begin
        // Compare prediction against expected
        if (pred_class == test_expected[img_idx][3:0]) begin
          $display("  Image %3d: PASS  predicted=%0d  expected=%0d  (%0d cycles)",
                   img_idx, pred_class, test_expected[img_idx], timeout_cnt);
          pass_count++;
        end else begin
          $display("  Image %3d: FAIL  predicted=%0d  expected=%0d  (%0d cycles)",
                   img_idx, pred_class, test_expected[img_idx], timeout_cnt);
          fail_count++;
        end
      end

      // Small gap between images
      repeat (5) @(posedge clk);
    end

    // ── Summary ──
    $display("============================================================");
    $display("  Results: %0d / %0d passed (%0d failed)",
             pass_count, NUM_TEST_IMAGES, fail_count);
    if (fail_count == 0)
      $display("  STATUS: ALL TESTS PASSED");
    else
      $display("  STATUS: SOME TESTS FAILED");
    $display("============================================================");

    $finish;
  end

  // ─── VCD dump (optional, for waveform viewing) ───
  initial begin
    if ($test$plusargs("VCD")) begin
      $dumpfile("cnn_top_tb.vcd");
      $dumpvars(0, cnn_top_tb);
    end
  end

endmodule
